const input = $input.first().json;
const company = String(input.company || input['Company'] || '').trim().replace(/\s+/g, ' ');
const objective = String(input.objective || input['Research objective'] || '').trim().replace(/\s+/g, ' ');
if (company.length < 2 || company.length > 200) throw new Error('Company must be 2-200 characters.');
if (objective.length < 20 || objective.length > 2000) throw new Error('Objective must be 20-2000 characters.');
const crypto = require('crypto');
const dedupe_key = crypto.createHash('sha256').update(company.toLowerCase() + '|' + objective.toLowerCase() + '|v1').digest('hex').slice(0, 32);
return [{ json: { company, objective, dedupe_key } }];

const row = $input.first().json;
const esc = s => String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');
if (!row.report_json) {
  return [{ json: { html: '<h1>No report found</h1><p>No completed assessment exists for this company and objective yet. If you recently submitted it, research may still be running — try again in a few minutes.</p>' } }];
}
const rep = JSON.parse(row.report_json);
const badge = { supported: 'color: #166534', contradicted: 'color: #991b1b', insufficient_evidence: 'color: #92400e' };
const rows = rep.findings.map(f =>
  '<div style="border:1px solid #e5e7eb;border-radius:8px;padding:12px;margin:10px 0">' +
  '<strong>' + esc(f.claim) + '</strong>' +
  '<div style="margin-top:6px;font-size:13px"><span style="' + (badge[f.verification]||'') + '"><b>' + esc(f.verification) + '</b></span>' +
  ' &middot; ' + esc(f.topic) + ' &middot; severity: ' + esc(f.severity) + '</div>' +
  (f.source_url ? '<div style="margin-top:6px;font-size:13px"><a href="' + esc(f.source_url) + '">' + esc(f.source_title || f.source_url) + '</a></div>' : '<div style="margin-top:6px;font-size:13px;color:#6b7280">No source</div>') +
  (f.evidence ? '<blockquote style="margin:8px 0 0;padding-left:10px;border-left:3px solid #d1d5db;color:#4b5563;font-size:13px">' + esc(f.evidence) + '</blockquote>' : '') +
  '</div>'
).join('');
const html = '<h1>VendorProof Report</h1><h2>' + esc(rep.vendor) + '</h2>' +
  '<p style="color:#6b7280;font-size:14px">' + esc(rep.objective) + '</p>' +
  '<p>Status: <b>' + esc(rep.status) + '</b> &middot; Review required: <b>' + (rep.requires_review ? 'YES' : 'no') + '</b> &middot; ' + esc(rep.generated_at) + '</p>' +
  (rep.review_reasons && rep.review_reasons.length ? '<p style="color:#991b1b">Review reasons: ' + esc(rep.review_reasons.join(', ')) + '</p>' : '') +
  '<h3>Assessment</h3><p>' + esc(rep.assessment) + '</p><h3>Findings (' + rep.findings.length + ')</h3>' + rows;
return [{ json: { html } }];
